// Decide who gets the review request (or the single reminder) today.
// Double idempotency guard: status must be 'open' AND the step's flag must be empty.
// The reminder is anchored to request_sent, so it can never fire before the ask itself.
const cfg = $('⚙️ Your settings').first().json;
const today = new Date();
today.setHours(0, 0, 0, 0);
const daysSince = (dateStr) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return Math.floor((today - d) / 86400000);
};
const due = [];

for (const item of $('Read all customers').all()) {
  const row = item.json;
  if (String(row.status || '').trim().toLowerCase() !== 'open') continue;
  if (!row.job_date || !row.customer_email) continue;

  let step = null;
  if (!row.request_sent) {
    const days = daysSince(row.job_date);
    if (days !== null && days >= cfg.requestOffset) step = 1;
  } else if (!row.reminder_sent) {
    const days = daysSince(row.request_sent);
    if (days !== null && days >= cfg.reminderGap) step = 2;
  }
  if (!step) continue;

  const fill = (t) => String(t)
    .replaceAll('{customer_name}', row.customer_name || 'there')
    .replaceAll('{job_description}', row.job_description || 'your project')
    .replaceAll('{review_link}', cfg.reviewLink)
    .replaceAll('{your_name}', cfg.yourName)
    .replaceAll('{business_name}', cfg.businessName);

  due.push({
    json: {
      job_id: row.job_id,
      customer_email: row.customer_email,
      step,
      subject: fill(cfg['subject' + step]),
      body: fill(cfg['body' + step]),
      flag_column: step === 1 ? 'request_sent' : 'reminder_sent',
    },
  });
}

return due;

// Fix the dynamic column name into a concrete key before writing back —
// the Sheets node maps plain input fields to columns; expression keys are not evaluated.
const q = $('One customer at a time').item.json;
const stamp = { job_id: q.job_id };
stamp[q.flag_column] = $now.toFormat('yyyy-MM-dd');
return [{ json: stamp }];
